// Cubemap viewer
//
// Shows the cubemap on channel 0 in two ways, so the six faces can be checked:
//   top     the faces unfolded as a cross, each with a coloured frame
//   bottom  the whole cubemap as a panorama (the middle looks along +Z)
//
// Put together correctly, the cross reads as one connected picture and the panorama has no seams.
//
// Frame colours   +X red   -X dark red   +Y green   -Y dark green   +Z blue   -Z dark blue
//
// Runs unchanged on Shadertoy, so the two can be compared side by side.

// Set to 1 to tint the panorama by face, which shows where the faces meet
#ifndef FACE_TINT
#define FACE_TINT 0
#endif

#define PI 3.14159265

// The direction through a point on a face. st runs 0..1 across the face, t downwards.
// This is the OpenGL cube map convention, which is what Shadertoy uses.
vec3 faceDir(int face, vec2 st)
{
	float sc = st.x * 2.0 - 1.0;
	float tc = st.y * 2.0 - 1.0;
	if (face == 0) return vec3( 1.0, -tc, -sc);
	if (face == 1) return vec3(-1.0, -tc,  sc);
	if (face == 2) return vec3( sc,  1.0,  tc);
	if (face == 3) return vec3( sc, -1.0, -tc);
	if (face == 4) return vec3( sc, -tc,  1.0);
	return vec3(-sc, -tc, -1.0);
}

// Which face a direction hits
int faceOf(vec3 d)
{
	vec3 a = abs(d);
	if (a.x >= a.y && a.x >= a.z) return d.x > 0.0 ? 0 : 1;
	if (a.y >= a.z) return d.y > 0.0 ? 2 : 3;
	return d.z > 0.0 ? 4 : 5;
}

vec3 faceColor(int face)
{
	if (face == 0) return vec3(1.0, 0.0, 0.0);
	if (face == 1) return vec3(0.5, 0.0, 0.0);
	if (face == 2) return vec3(0.0, 1.0, 0.0);
	if (face == 3) return vec3(0.0, 0.5, 0.0);
	if (face == 4) return vec3(0.0, 0.4, 1.0);
	return vec3(0.0, 0.0, 0.5);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
	vec2 R = iResolution.xy;
	float c = floor(min(R.x / 4.0, R.y * 0.45 / 3.0));                    // the size of one face in the cross
	vec2 origin = vec2(floor((R.x - 4.0 * c) * 0.5), R.y - 3.0 * c);      // the lower left corner of the cross
	vec2 p = fragCoord - origin;
	vec3 col = vec3(0.0);

	if (p.y >= 0.0)
	{
		// the cross: four cells across and three down, counted from the top
		vec2 cell = floor(p / c);
		int column = int(cell.x);
		int row = 2 - int(cell.y);
		int face = -1;
		if (row == 0 && column == 1) face = 2;
		else if (row == 1 && column == 0) face = 1;
		else if (row == 1 && column == 1) face = 4;
		else if (row == 1 && column == 2) face = 0;
		else if (row == 1 && column == 3) face = 5;
		else if (row == 2 && column == 1) face = 3;

		col = vec3(0.08);
		if (face >= 0 && p.x >= 0.0)
		{
			vec2 local = (p - cell * c) / c;                              // 0..1 inside the cell, y upwards
			vec2 st = vec2(local.x, 1.0 - local.y);                       // t downwards
			col = textureLod(iChannel0, faceDir(face, st), 0.0).rgb;
			vec2 edge = min(local, 1.0 - local) * c;                      // distance to the edge in pixels
			if (min(edge.x, edge.y) < 3.0) col = faceColor(face);
		}
	}
	else
	{
		// the panorama, in the space below the cross
		vec2 uv = vec2(fragCoord.x / R.x, fragCoord.y / origin.y);
		float lon = (uv.x - 0.5) * 2.0 * PI;
		float lat = (uv.y - 0.5) * PI;
		vec3 d = vec3(cos(lat) * sin(lon), sin(lat), cos(lat) * cos(lon));
		col = textureLod(iChannel0, d, 0.0).rgb;
#if FACE_TINT
		col = mix(col, faceColor(faceOf(d)), 0.35);
#endif
	}
	fragColor = vec4(col, 1.0);
}
